package com.meterflow.credits;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="credit_notes")public class CreditNote{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(nullable=false)private String customerId;@Column(nullable=false,precision=18,scale=2)private BigDecimal amount;@Column(nullable=false)private String currency;@Column(nullable=false,length=500)private String reason;@Column(nullable=false)private Instant createdAt=Instant.now();protected CreditNote(){}public CreditNote(String c,BigDecimal a,String u,String r){customerId=c;amount=a;currency=u;reason=r;}public UUID getId(){return id;}public String getCustomerId(){return customerId;}public BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public String getReason(){return reason;}public Instant getCreatedAt(){return createdAt;}}
